import{_ as a,o,c as r,ae as i}from"./chunks/framework.BzQXgbNp.js";const u=JSON.parse('{"title":"Variable: APP_MESSAGES","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/shared-core/variables/APP_MESSAGES.md","filePath":"api-reference/shared-core/variables/APP_MESSAGES.md"}'),t={name:"api-reference/shared-core/variables/APP_MESSAGES.md"};function c(n,e,d,s,l,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<p><a href="./../"><strong>shared-core</strong></a></p><hr><p><a href="./../">shared-core</a> / APP_MESSAGES</p><h1 id="variable-app-messages" tabindex="-1">Variable: APP_MESSAGES <a class="header-anchor" href="#variable-app-messages" aria-label="Permalink to &quot;Variable: APP\\_MESSAGES&quot;">​</a></h1><blockquote><p><code>const</code> <strong>APP_MESSAGES</strong>: <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/Erladron/adcLosLocosV2/blob/ef8b35066458446779d596c924480fd02bae169f/projects/shared-core/src/lib/constants/app-messages.ts#L8" target="_blank" rel="noreferrer">constants/app-messages.ts:8</a></p><h2 id="type-declaration" tabindex="-1">Type Declaration <a class="header-anchor" href="#type-declaration" aria-label="Permalink to &quot;Type Declaration&quot;">​</a></h2><h3 id="adc-admin-err-0001" tabindex="-1">ADC_ADMIN_ERR_0001 <a class="header-anchor" href="#adc-admin-err-0001" aria-label="Permalink to &quot;ADC\\_ADMIN\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_ADMIN_ERR_0001</strong>: <code>string</code> = <code>&#39;Error aprobando usuario.&#39;</code></p></blockquote><h4 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de flujo: Error asíncrono al intentar invocar la mutación de estado a &#39;active&#39; sobre el usuario.</p><h3 id="adc-admin-err-0002" tabindex="-1">ADC_ADMIN_ERR_0002 <a class="header-anchor" href="#adc-admin-err-0002" aria-label="Permalink to &quot;ADC\\_ADMIN\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_ADMIN_ERR_0002</strong>: <code>string</code> = <code>&#39;Error rechazando usuario.&#39;</code></p></blockquote><h4 id="description-1" tabindex="-1">Description <a class="header-anchor" href="#description-1" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción en denegación: Fallo de red al intentar destruir el token o registrar el log de motivo de rechazo.</p><h3 id="adc-auth-err-0001" tabindex="-1">ADC_AUTH_ERR_0001 <a class="header-anchor" href="#adc-auth-err-0001" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0001</strong>: <code>string</code> = <code>&#39;Usuario no autenticado.&#39;</code></p></blockquote><h4 id="description-2" tabindex="-1">Description <a class="header-anchor" href="#description-2" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error emitido cuando una petición interceptada por el guard carece de token de sesión activo.</p><h3 id="adc-auth-err-0002" tabindex="-1">ADC_AUTH_ERR_0002 <a class="header-anchor" href="#adc-auth-err-0002" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0002</strong>: <code>string</code> = <code>&#39;Credenciales inválidas.&#39;</code></p></blockquote><h4 id="description-3" tabindex="-1">Description <a class="header-anchor" href="#description-3" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error genérico de login que evita dar pistas sobre si falló el correo o la clave por seguridad.</p><h3 id="adc-auth-err-0003" tabindex="-1">ADC_AUTH_ERR_0003 <a class="header-anchor" href="#adc-auth-err-0003" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0003</strong>: <code>string</code> = <code>&#39;Tu correo no está autorizado para registrarse.&#39;</code></p></blockquote><h4 id="description-4" tabindex="-1">Description <a class="header-anchor" href="#description-4" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Bloqueo en pre-alta: El email introducido no ha sido registrado previamente por la directiva en <code>invitedUsers</code>.</p><h3 id="adc-auth-err-0004" tabindex="-1">ADC_AUTH_ERR_0004 <a class="header-anchor" href="#adc-auth-err-0004" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0004&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0004</strong>: <code>string</code> = <code>&#39;Ya existe una cuenta registrada con este correo electrónico.&#39;</code></p></blockquote><h4 id="description-5" tabindex="-1">Description <a class="header-anchor" href="#description-5" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error de duplicidad: Intento de alta con un email que ya existe en el chasis de Firebase Authentication.</p><h3 id="adc-auth-err-0005" tabindex="-1">ADC_AUTH_ERR_0005 <a class="header-anchor" href="#adc-auth-err-0005" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0005&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0005</strong>: <code>string</code> = <code>&#39;La contraseña debe tener al menos 6 caracteres.&#39;</code></p></blockquote><h4 id="description-6" tabindex="-1">Description <a class="header-anchor" href="#description-6" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación de robustez: Longitud de caracteres de la contraseña inferior al mínimo exigido por las políticas.</p><h3 id="adc-auth-err-0006" tabindex="-1">ADC_AUTH_ERR_0006 <a class="header-anchor" href="#adc-auth-err-0006" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0006&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0006</strong>: <code>string</code> = <code>&#39;El correo electrónico no es válido.&#39;</code></p></blockquote><h4 id="description-7" tabindex="-1">Description <a class="header-anchor" href="#description-7" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Estructura de formulario: La cadena de texto de entrada no supera los patrones de formato de un email legítimo.</p><h3 id="adc-auth-err-0007" tabindex="-1">ADC_AUTH_ERR_0007 <a class="header-anchor" href="#adc-auth-err-0007" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0007&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0007</strong>: <code>string</code> = <code>&#39;Error registrando usuario.&#39;</code></p></blockquote><h4 id="description-8" tabindex="-1">Description <a class="header-anchor" href="#description-8" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Fallo en el motor de Firebase Auth: Excepción no controlada durante el proceso de empaquetado del registro.</p><h3 id="adc-auth-err-0008" tabindex="-1">ADC_AUTH_ERR_0008 <a class="header-anchor" href="#adc-auth-err-0008" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0008&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0008</strong>: <code>string</code> = <code>&#39;Por favor, introduce tu email y contraseña.&#39;</code></p></blockquote><h4 id="description-9" tabindex="-1">Description <a class="header-anchor" href="#description-9" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación rápida de login: El usuario ha dejado en blanco los inputs obligatorios de acceso de la pantalla.</p><h3 id="adc-auth-err-0009" tabindex="-1">ADC_AUTH_ERR_0009 <a class="header-anchor" href="#adc-auth-err-0009" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0009&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0009</strong>: <code>string</code> = <code>&#39;Tu cuenta ha sido cancelada. Contacta con administración.&#39;</code></p></blockquote><h4 id="description-10" tabindex="-1">Description <a class="header-anchor" href="#description-10" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Bloqueo perimetral: Intento de login de un socio con estado lógico &#39;inactive&#39; o suspendido por el club.</p><h3 id="adc-auth-err-0010" tabindex="-1">ADC_AUTH_ERR_0010 <a class="header-anchor" href="#adc-auth-err-0010" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0010&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0010</strong>: <code>string</code> = <code>&#39;Error actualizando credenciales.&#39;</code></p></blockquote><h4 id="description-11" tabindex="-1">Description <a class="header-anchor" href="#description-11" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de credenciales: Fallo de persistencia al intentar mutar o re-autenticar la cuenta del usuario.</p><h3 id="adc-auth-err-0011" tabindex="-1">ADC_AUTH_ERR_0011 <a class="header-anchor" href="#adc-auth-err-0011" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0011&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0011</strong>: <code>string</code> = <code>&#39;Usuario o contraseña incorrectos.&#39;</code></p></blockquote><h4 id="description-12" tabindex="-1">Description <a class="header-anchor" href="#description-12" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error en pantalla de login: No hay concordancia biunívoca entre los campos introducidos y los registros.</p><h3 id="adc-auth-err-0012" tabindex="-1">ADC_AUTH_ERR_0012 <a class="header-anchor" href="#adc-auth-err-0012" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0012&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0012</strong>: <code>string</code> = <code>&#39;Usuario o contraseña incorrectos.&#39;</code></p></blockquote><h4 id="description-13" tabindex="-1">Description <a class="header-anchor" href="#description-13" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Fallo de verificación de clave espejo: Doble check erróneo en el flujo de credenciales.</p><h3 id="adc-auth-err-0013" tabindex="-1">ADC_AUTH_ERR_0013 <a class="header-anchor" href="#adc-auth-err-0013" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0013&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0013</strong>: <code>string</code> = <code>&#39;Demasiados intentos. Inténtalo más tarde.&#39;</code></p></blockquote><h4 id="description-14" tabindex="-1">Description <a class="header-anchor" href="#description-14" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Defensa perimetral: Alerta Toast disparada tras saturar el umbral de reintentos permitidos por la API.</p><h3 id="adc-auth-err-0014" tabindex="-1">ADC_AUTH_ERR_0014 <a class="header-anchor" href="#adc-auth-err-0014" aria-label="Permalink to &quot;ADC\\_AUTH\\_ERR\\_0014&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_ERR_0014</strong>: <code>string</code> = <code>&#39;Error de conexión con Firebase.&#39;</code></p></blockquote><h4 id="description-15" tabindex="-1">Description <a class="header-anchor" href="#description-15" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error físico de socket: Pérdida total de conexión o timeout con los balanceadores de carga de Google Cloud.</p><h3 id="adc-auth-inf-0001" tabindex="-1">ADC_AUTH_INF_0001 <a class="header-anchor" href="#adc-auth-inf-0001" aria-label="Permalink to &quot;ADC\\_AUTH\\_INF\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_AUTH_INF_0001</strong>: <code>string</code> = <code>&#39;Cuenta creada correctamente.&#39;</code></p></blockquote><h4 id="description-16" tabindex="-1">Description <a class="header-anchor" href="#description-16" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Flujo de alta y sincronización con el backend completado de forma correcta.</p><h3 id="adc-event-err-0001" tabindex="-1">ADC_EVENT_ERR_0001 <a class="header-anchor" href="#adc-event-err-0001" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0001</strong>: <code>string</code> = <code>&#39;No se ha podido guardar el evento. Por favor, inténtalo de nuevo.&#39;</code></p></blockquote><h4 id="description-17" tabindex="-1">Description <a class="header-anchor" href="#description-17" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción NoSQL: Fallo de concurrencia o red al intentar consolidar los formularios del evento en <code>/events</code>.</p><h3 id="adc-event-err-0002" tabindex="-1">ADC_EVENT_ERR_0002 <a class="header-anchor" href="#adc-event-err-0002" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0002</strong>: <code>string</code> = <code>&#39;Error al registrar tu asistencia. Revisa tu conexión.&#39;</code></p></blockquote><h4 id="description-18" tabindex="-1">Description <a class="header-anchor" href="#description-18" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de asistencia: Error al insertar el UID del socio en la subcolección atómica <code>/attendance</code>.</p><h3 id="adc-event-err-0003" tabindex="-1">ADC_EVENT_ERR_0003 <a class="header-anchor" href="#adc-event-err-0003" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0003</strong>: <code>string</code> = <code>&#39;No se ha podido eliminar el evento.&#39;</code></p></blockquote><h4 id="description-19" tabindex="-1">Description <a class="header-anchor" href="#description-19" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción destructiva: Error asíncrono al intentar borrar la convocatoria o ejecutar el lote en cascada.</p><h3 id="adc-event-err-0004" tabindex="-1">ADC_EVENT_ERR_0004 <a class="header-anchor" href="#adc-event-err-0004" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0004&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0004</strong>: <code>string</code> = <code>&#39;El evento no existe o ha sido eliminado.&#39;</code></p></blockquote><h4 id="description-20" tabindex="-1">Description <a class="header-anchor" href="#description-20" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error de navegación: El ID del evento solicitado por la URL de la app ha sido borrado físicamente por un directivo.</p><h3 id="adc-event-err-0005" tabindex="-1">ADC_EVENT_ERR_0005 <a class="header-anchor" href="#adc-event-err-0005" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0005&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0005</strong>: <code>string</code> = <code>&#39;Error al cargar los datos del evento.&#39;</code></p></blockquote><h4 id="description-21" tabindex="-1">Description <a class="header-anchor" href="#description-21" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de descarga: Error de red al intentar recuperar los detalles, imágenes o diccionarios del evento.</p><h3 id="adc-event-err-0006" tabindex="-1">ADC_EVENT_ERR_0006 <a class="header-anchor" href="#adc-event-err-0006" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0006&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0006</strong>: <code>string</code> = <code>&#39;La fecha y hora inicio no puede ser menor a la actual.&#39;</code></p></blockquote><h4 id="description-22" tabindex="-1">Description <a class="header-anchor" href="#description-22" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Coherencia temporal: El formulario de creación ha detectado que la fecha de inicio pertenece al pasado.</p><h3 id="adc-event-err-0007" tabindex="-1">ADC_EVENT_ERR_0007 <a class="header-anchor" href="#adc-event-err-0007" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0007&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0007</strong>: <code>string</code> = <code>&#39;La fecha y hora de fin del evento debe ser posterior a la de inicio.&#39;</code></p></blockquote><h4 id="description-23" tabindex="-1">Description <a class="header-anchor" href="#description-23" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Coherencia temporal: Validación fallida debido a rangos cruzados (la fecha de fin es previa al inicio).</p><h3 id="adc-event-err-0008" tabindex="-1">ADC_EVENT_ERR_0008 <a class="header-anchor" href="#adc-event-err-0008" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0008&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0008</strong>: <code>string</code> = <code>&#39;¡Aforo completo! Lo sentimos, ya no quedan plazas libres para este evento.&#39;</code></p></blockquote><h4 id="description-24" tabindex="-1">Description <a class="header-anchor" href="#description-24" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Control de aforo atómico: El contador de plazas <code>attendeeCount</code> ha alcanzado el máximo configurable <code>maxAttendees</code>.</p><h3 id="adc-event-err-0009" tabindex="-1">ADC_EVENT_ERR_0009 <a class="header-anchor" href="#adc-event-err-0009" aria-label="Permalink to &quot;ADC\\_EVENT\\_ERR\\_0009&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_ERR_0009</strong>: <code>string</code> = <code>&#39;El límite de invitados por socio es obligatorio para los eventos de feria y debe ser igual o superior a 1.&#39;</code></p></blockquote><h4 id="description-25" tabindex="-1">Description <a class="header-anchor" href="#description-25" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación estructural: Los formularios exigen definir el cupo dinámico de pases permitidos para eventos tipo feria.</p><h3 id="adc-event-inf-0001" tabindex="-1">ADC_EVENT_INF_0001 <a class="header-anchor" href="#adc-event-inf-0001" aria-label="Permalink to &quot;ADC\\_EVENT\\_INF\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_INF_0001</strong>: <code>string</code> = <code>&#39;¡Evento convocado con éxito!&#39;</code></p></blockquote><h4 id="description-26" tabindex="-1">Description <a class="header-anchor" href="#description-26" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Convocatoria registrada y visible de forma instantánea en la app móvil.</p><h3 id="adc-event-inf-0002" tabindex="-1">ADC_EVENT_INF_0002 <a class="header-anchor" href="#adc-event-inf-0002" aria-label="Permalink to &quot;ADC\\_EVENT\\_INF\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_INF_0002</strong>: <code>string</code> = <code>&#39;Datos del evento actualizados correctamente.&#39;</code></p></blockquote><h4 id="description-27" tabindex="-1">Description <a class="header-anchor" href="#description-27" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Modificaciones consolidadas y enviadas de forma limpia hacia la base de datos Firestore.</p><h3 id="adc-event-inf-0003" tabindex="-1">ADC_EVENT_INF_0003 <a class="header-anchor" href="#adc-event-inf-0003" aria-label="Permalink to &quot;ADC\\_EVENT\\_INF\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_EVENT_INF_0003</strong>: <code>string</code> = <code>&#39;¡Asistencia confirmada! Te esperamos.&#39;</code></p></blockquote><h4 id="description-28" tabindex="-1">Description <a class="header-anchor" href="#description-28" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Transacción atómica completada con éxito y plaza en el evento asegurada.</p><h3 id="adc-fees-err-0001" tabindex="-1">ADC_FEES_ERR_0001 <a class="header-anchor" href="#adc-fees-err-0001" aria-label="Permalink to &quot;ADC\\_FEES\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_FEES_ERR_0001</strong>: <code>string</code> = <code>&#39;Acceso denegado. Es necesario estar al corriente de pago de la cuota para poder apuntarse a este evento.&#39;</code></p></blockquote><h4 id="description-29" tabindex="-1">Description <a class="header-anchor" href="#description-29" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Bloqueo de agenda: Intercepta la confirmación de asistencia bloqueando el botón si el socio adeuda cuotas.</p><h3 id="adc-fees-err-0002" tabindex="-1">ADC_FEES_ERR_0002 <a class="header-anchor" href="#adc-fees-err-0002" aria-label="Permalink to &quot;ADC\\_FEES\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_FEES_ERR_0002</strong>: <code>string</code> = <code>&#39;Operación bloqueada. No se permiten emitir o desplegar credenciales feriales si el socio presenta cuotas pendientes.&#39;</code></p></blockquote><h4 id="description-30" tabindex="-1">Description <a class="header-anchor" href="#description-30" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Bloqueo ferial: Impide generar pases de caseta en <code>event-access</code> si se detecta estado de impago en el perfil.</p><h3 id="adc-fees-err-0003" tabindex="-1">ADC_FEES_ERR_0003 <a class="header-anchor" href="#adc-fees-err-0003" aria-label="Permalink to &quot;ADC\\_FEES\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_FEES_ERR_0003</strong>: <code>string</code> = <code>&#39;No se pudo guardar la actualización financiera. Revisa tu conexión de red o permisos.&#39;</code></p></blockquote><h4 id="description-31" tabindex="-1">Description <a class="header-anchor" href="#description-31" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción en consola de cuotas: Error asíncrono al intentar mutar el booleano financiero desde el panel masivo.</p><h3 id="adc-inv-err-0001" tabindex="-1">ADC_INV_ERR_0001 <a class="header-anchor" href="#adc-inv-err-0001" aria-label="Permalink to &quot;ADC\\_INV\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_INV_ERR_0001</strong>: <code>string</code> = <code>&#39;Por favor, introduce un correo electrónico.&#39;</code></p></blockquote><h4 id="description-32" tabindex="-1">Description <a class="header-anchor" href="#description-32" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación administrativa: Se ha pulsado emitir invitación dejando vacío el campo del email destino.</p><h3 id="adc-inv-err-0002" tabindex="-1">ADC_INV_ERR_0002 <a class="header-anchor" href="#adc-inv-err-0002" aria-label="Permalink to &quot;ADC\\_INV\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_INV_ERR_0002</strong>: <code>string</code> = <code>&#39;Introduce un email válido.&#39;</code></p></blockquote><h4 id="description-33" tabindex="-1">Description <a class="header-anchor" href="#description-33" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación de estructura: El email del aspirante introducido en la consola no supera la expresión regular.</p><h3 id="adc-inv-err-0003" tabindex="-1">ADC_INV_ERR_0003 <a class="header-anchor" href="#adc-inv-err-0003" aria-label="Permalink to &quot;ADC\\_INV\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_INV_ERR_0003</strong>: <code>string</code> = <code>&#39;Error enviando invitación.&#39;</code></p></blockquote><h4 id="description-34" tabindex="-1">Description <a class="header-anchor" href="#description-34" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de pasarela: Fallo en Cloud Functions o en el servidor SMTP al despachar el correo con diseño premium.</p><h3 id="adc-inv-err-0004" tabindex="-1">ADC_INV_ERR_0004 <a class="header-anchor" href="#adc-inv-err-0004" aria-label="Permalink to &quot;ADC\\_INV\\_ERR\\_0004&quot;">​</a></h3><blockquote><p><strong>ADC_INV_ERR_0004</strong>: <code>string</code> = <code>&#39;El usuario ya pertenece a la aplicación.&#39;</code></p></blockquote><h4 id="description-35" tabindex="-1">Description <a class="header-anchor" href="#description-35" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Regla de negocio: Intento de invitar a una persona cuyo email ya consta como cuenta activa en la peña.</p><h3 id="adc-inv-err-0005" tabindex="-1">ADC_INV_ERR_0005 <a class="header-anchor" href="#adc-inv-err-0005" aria-label="Permalink to &quot;ADC\\_INV\\_ERR\\_0005&quot;">​</a></h3><blockquote><p><strong>ADC_INV_ERR_0005</strong>: <code>string</code> = <code>&#39;Ya existe una invitación para este correo.&#39;</code></p></blockquote><h4 id="description-36" tabindex="-1">Description <a class="header-anchor" href="#description-36" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Control de duplicidad: Ya se localiza un token inmutable en caliente emitido y pendiente para esa misma cuenta.</p><h3 id="adc-inv-err-0006" tabindex="-1">ADC_INV_ERR_0006 <a class="header-anchor" href="#adc-inv-err-0006" aria-label="Permalink to &quot;ADC\\_INV\\_ERR\\_0006&quot;">​</a></h3><blockquote><p><strong>ADC_INV_ERR_0006</strong>: <code>string</code> = <code>&#39;No existe ninguna invitación para este correo.&#39;</code></p></blockquote><h4 id="description-37" tabindex="-1">Description <a class="header-anchor" href="#description-37" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación de token web: El enlace pulsado por el usuario no se corresponde con ningún UUID de <code>invitedUsers</code>.</p><h3 id="adc-inv-inf-0001" tabindex="-1">ADC_INV_INF_0001 <a class="header-anchor" href="#adc-inv-inf-0001" aria-label="Permalink to &quot;ADC\\_INV\\_INF\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_INV_INF_0001</strong>: <code>string</code> = <code>&#39;Invitación enviada correctamente.&#39;</code></p></blockquote><h4 id="description-38" tabindex="-1">Description <a class="header-anchor" href="#description-38" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Documento cerrojo lógico creado en Firestore y correo electrónico despachado.</p><h3 id="adc-pass-err-0001" tabindex="-1">ADC_PASS_ERR_0001 <a class="header-anchor" href="#adc-pass-err-0001" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0001</strong>: <code>string</code> = <code>&#39;Límite superado. Solo puedes invitar a un máximo de 6 personas por día.&#39;</code></p></blockquote><h4 id="description-39" tabindex="-1">Description <a class="header-anchor" href="#description-39" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Restricción de negocio: El socio ha superado el cupo estricto de invitaciones externas reguladas para el día de hoy.</p><h3 id="adc-pass-err-0002" tabindex="-1">ADC_PASS_ERR_0002 <a class="header-anchor" href="#adc-pass-err-0002" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0002</strong>: <code>string</code> = <code>&#39;El código QR escaneado no corresponde a ningún pase de feria válido.&#39;</code></p></blockquote><h4 id="description-40" tabindex="-1">Description <a class="header-anchor" href="#description-40" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Terminal de portería: El decodificador del plugin de la cámara arroja un payload ilegítimo o fraudulento.</p><h3 id="adc-pass-err-0003" tabindex="-1">ADC_PASS_ERR_0003 <a class="header-anchor" href="#adc-pass-err-0003" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0003</strong>: <code>string</code> = <code>&#39;Acceso denegado. Este pase no es válido para la fecha de hoy.&#39;</code></p></blockquote><h4 id="description-41" tabindex="-1">Description <a class="header-anchor" href="#description-41" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación de acceso en puerta: El escáner rechaza el pase porque la fecha actual no cubre la vigencia del abono.</p><h3 id="adc-pass-err-0004" tabindex="-1">ADC_PASS_ERR_0004 <a class="header-anchor" href="#adc-pass-err-0004" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0004&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0004</strong>: <code>string</code> = <code>&#39;No se pudo emitir la invitación. Verifica tu conexión.&#39;</code></p></blockquote><h4 id="description-42" tabindex="-1">Description <a class="header-anchor" href="#description-42" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de inserción: Error asíncrono de red al intentar insertar el pase digital en <code>event-access</code>.</p><h3 id="adc-pass-err-0005" tabindex="-1">ADC_PASS_ERR_0005 <a class="header-anchor" href="#adc-pass-err-0005" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0005&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0005</strong>: <code>string</code> = <code>&#39;No se pudo anular el pase. Inténtalo de nuevo más tarde.&#39;</code></p></blockquote><h4 id="description-43" tabindex="-1">Description <a class="header-anchor" href="#description-43" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción destructiva: Fallo al intentar borrar el documento de la credencial desde el listado del socio.</p><h3 id="adc-pass-err-0006" tabindex="-1">ADC_PASS_ERR_0006 <a class="header-anchor" href="#adc-pass-err-0006" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0006&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0006</strong>: <code>string</code> = <code>&#39;Debes seleccionar un invitado del listado desplegable o escribir un nombre.&#39;</code></p></blockquote><h4 id="description-44" tabindex="-1">Description <a class="header-anchor" href="#description-44" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación de formulario ferial: Argumento obligatorio nulo al intentar generar un pase sin identidad destino.</p><h3 id="adc-pass-err-0007" tabindex="-1">ADC_PASS_ERR_0007 <a class="header-anchor" href="#adc-pass-err-0007" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0007&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0007</strong>: <code>string</code> = <code>&#39;No tienes ningún pase de feria activo disponible para la jornada de hoy.&#39;</code></p></blockquote><h4 id="description-45" tabindex="-1">Description <a class="header-anchor" href="#description-45" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Monitorización reactiva: El snapshot determina que el usuario logueado carece de pases válidos vigentes hoy.</p><h3 id="adc-pass-err-0008" tabindex="-1">ADC_PASS_ERR_0008 <a class="header-anchor" href="#adc-pass-err-0008" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0008&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0008</strong>: <code>string</code> = <code>&#39;Acceso denegado. El socio no se encuentra en estado activo en el sistema.&#39;</code></p></blockquote><h4 id="description-46" tabindex="-1">Description <a class="header-anchor" href="#description-46" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Control en puerta: El carnet escaneado pertenece a una cuenta suspendida o bloqueada por la directiva.</p><h3 id="adc-pass-err-0009" tabindex="-1">ADC_PASS_ERR_0009 <a class="header-anchor" href="#adc-pass-err-0009" aria-label="Permalink to &quot;ADC\\_PASS\\_ERR\\_0009&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_ERR_0009</strong>: <code>string</code> = <code>&#39;Acceso denegado. El tipo de usuario no dispone de credenciales de acceso de socio.&#39;</code></p></blockquote><h4 id="description-47" tabindex="-1">Description <a class="header-anchor" href="#description-47" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Control de portería: El tipo de rol asignado al usuario carece por completo de permisos de admisión ferial.</p><h3 id="adc-pass-inf-0001" tabindex="-1">ADC_PASS_INF_0001 <a class="header-anchor" href="#adc-pass-inf-0001" aria-label="Permalink to &quot;ADC\\_PASS\\_INF\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_INF_0001</strong>: <code>string</code> = <code>&#39;Pase de caseta emitido correctamente.&#39;</code></p></blockquote><h4 id="description-48" tabindex="-1">Description <a class="header-anchor" href="#description-48" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Pase relacional insertado y disponible para el despliegue del código QR del invitado.</p><h3 id="adc-pass-inf-0002" tabindex="-1">ADC_PASS_INF_0002 <a class="header-anchor" href="#adc-pass-inf-0002" aria-label="Permalink to &quot;ADC\\_PASS\\_INF\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_INF_0002</strong>: <code>string</code> = <code>&#39;El pase ha sido anulado correctamente.&#39;</code></p></blockquote><h4 id="description-49" tabindex="-1">Description <a class="header-anchor" href="#description-49" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Credencial purgada del servidor, quedando inmediatamente desvinculada e invalidada.</p><h3 id="adc-pass-inf-0003" tabindex="-1">ADC_PASS_INF_0003 <a class="header-anchor" href="#adc-pass-inf-0003" aria-label="Permalink to &quot;ADC\\_PASS\\_INF\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_PASS_INF_0003</strong>: <code>string</code> = <code>&#39;¡Pase de Feria disponible! Hemos generado automáticamente tu credencial de acceso para la caseta de feria.&#39;</code></p></blockquote><h4 id="description-50" tabindex="-1">Description <a class="header-anchor" href="#description-50" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Inicialización de billetera: El onSnapshot detecta un abono vigente hoy y activa el acceso lateral de forma automática.</p><h3 id="adc-sys-err-0001" tabindex="-1">ADC_SYS_ERR_0001 <a class="header-anchor" href="#adc-sys-err-0001" aria-label="Permalink to &quot;ADC\\_SYS\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_SYS_ERR_0001</strong>: <code>string</code> = <code>&#39;Error inesperado del sistema.&#39;</code></p></blockquote><h4 id="description-51" tabindex="-1">Description <a class="header-anchor" href="#description-51" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Interceptor fallback general: Excepción de software no controlada atrapada en el catch definitivo.</p><h3 id="adc-sys-err-0002" tabindex="-1">ADC_SYS_ERR_0002 <a class="header-anchor" href="#adc-sys-err-0002" aria-label="Permalink to &quot;ADC\\_SYS\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_SYS_ERR_0002</strong>: <code>string</code> = <code>&#39;Error de conexión.&#39;</code></p></blockquote><h4 id="description-52" tabindex="-1">Description <a class="header-anchor" href="#description-52" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error físico offline: El hardware del dispositivo no presenta respuesta de red o sockets abiertos.</p><h3 id="adc-sys-err-0003" tabindex="-1">ADC_SYS_ERR_0003 <a class="header-anchor" href="#adc-sys-err-0003" aria-label="Permalink to &quot;ADC\\_SYS\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_SYS_ERR_0003</strong>: <code>string</code> = <code>&#39;No tienes permisos para realizar esta acción.&#39;</code></p></blockquote><h4 id="description-53" tabindex="-1">Description <a class="header-anchor" href="#description-53" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Seguridad de Firebase rules: El token de sesión del usuario ha violado las restricciones perimetrales del servidor.</p><h3 id="adc-sys-err-0004" tabindex="-1">ADC_SYS_ERR_0004 <a class="header-anchor" href="#adc-sys-err-0004" aria-label="Permalink to &quot;ADC\\_SYS\\_ERR\\_0004&quot;">​</a></h3><blockquote><p><strong>ADC_SYS_ERR_0004</strong>: <code>string</code> = <code>&#39;Servicio temporalmente no disponible.&#39;</code></p></blockquote><h4 id="description-54" tabindex="-1">Description <a class="header-anchor" href="#description-54" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Error de Cloud Run: Caída del backend serverless en Node.js 24 o mantenimiento crítico de servicios de Firebase.</p><h3 id="adc-sys-err-0005" tabindex="-1">ADC_SYS_ERR_0005 <a class="header-anchor" href="#adc-sys-err-0005" aria-label="Permalink to &quot;ADC\\_SYS\\_ERR\\_0005&quot;">​</a></h3><blockquote><p><strong>ADC_SYS_ERR_0005</strong>: <code>string</code> = <code>&#39;Fallo de hardware: El dispositivo no ha podido procesar u optimizar la fotografía seleccionada.&#39;</code></p></blockquote><h4 id="description-55" tabindex="-1">Description <a class="header-anchor" href="#description-55" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Fallo de hardware: El dispositivo no ha podido procesar u optimizar la fotografía seleccionada.</p><h3 id="adc-user-err-0001" tabindex="-1">ADC_USER_ERR_0001 <a class="header-anchor" href="#adc-user-err-0001" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0001</strong>: <code>string</code> = <code>&#39;Error guardando usuario.&#39;</code></p></blockquote><h4 id="description-56" tabindex="-1">Description <a class="header-anchor" href="#description-56" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción NoSQL: No se ha podido consolidar la escritura del documento de datos del socio en Firestore.</p><h3 id="adc-user-err-0002" tabindex="-1">ADC_USER_ERR_0002 <a class="header-anchor" href="#adc-user-err-0002" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0002</strong>: <code>string</code> = <code>&#39;Error actualizando datos personales.&#39;</code></p></blockquote><h4 id="description-57" tabindex="-1">Description <a class="header-anchor" href="#description-57" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Excepción de formulario: Fallo asíncrono al guardar el bloque civil editado por el usuario en su perfil.</p><h3 id="adc-user-err-0003" tabindex="-1">ADC_USER_ERR_0003 <a class="header-anchor" href="#adc-user-err-0003" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0003&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0003</strong>: <code>string</code> = <code>&#39;Los emails no coinciden.&#39;</code></p></blockquote><h4 id="description-58" tabindex="-1">Description <a class="header-anchor" href="#description-58" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación del frontend: Los correos suministrados en los dos inputs del formulario de alta discrepan.</p><h3 id="adc-user-err-0004" tabindex="-1">ADC_USER_ERR_0004 <a class="header-anchor" href="#adc-user-err-0004" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0004&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0004</strong>: <code>string</code> = <code>&#39;Las contraseñas no coinciden.&#39;</code></p></blockquote><h4 id="description-59" tabindex="-1">Description <a class="header-anchor" href="#description-59" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación del frontend: La contraseña y su campo de confirmación espejo no presentan idéntica cadena.</p><h3 id="adc-user-err-0005" tabindex="-1">ADC_USER_ERR_0005 <a class="header-anchor" href="#adc-user-err-0005" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0005&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0005</strong>: <code>string</code> = <code>&#39;Complete todos los campos.&#39;</code></p></blockquote><h4 id="description-60" tabindex="-1">Description <a class="header-anchor" href="#description-60" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Validación de campos obligatorios: El usuario ha dejado vacíos inputs requeridos con asterisco (*) en la UI.</p><h3 id="adc-user-err-0006" tabindex="-1">ADC_USER_ERR_0006 <a class="header-anchor" href="#adc-user-err-0006" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0006&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0006</strong>: <code>string</code> = <code>&#39;No se ha podido procesar la baja de tu cuenta. Por favor, inténtalo de nuevo o contacta con la directiva.&#39;</code></p></blockquote><h4 id="description-61" tabindex="-1">Description <a class="header-anchor" href="#description-61" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Traducción semántica oficial del fallo de autobaja</p><h3 id="adc-user-err-0007" tabindex="-1">ADC_USER_ERR_0007 <a class="header-anchor" href="#adc-user-err-0007" aria-label="Permalink to &quot;ADC\\_USER\\_ERR\\_0007&quot;">​</a></h3><blockquote><p><strong>ADC_USER_ERR_0007</strong>: <code>string</code> = <code>&#39;Baja bloqueada. No puedes eliminar tu cuenta si tienes cuotas pendientes de pago. Ponte en contacto con tesorería.&#39;</code></p></blockquote><h4 id="description-62" tabindex="-1">Description <a class="header-anchor" href="#description-62" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Traducción semántica para el bloqueo de baja por morosidad</p><h3 id="adc-user-inf-0001" tabindex="-1">ADC_USER_INF_0001 <a class="header-anchor" href="#adc-user-inf-0001" aria-label="Permalink to &quot;ADC\\_USER\\_INF\\_0001&quot;">​</a></h3><blockquote><p><strong>ADC_USER_INF_0001</strong>: <code>string</code> = <code>&#39;Usuario aprobado correctamente.&#39;</code></p></blockquote><h4 id="description-63" tabindex="-1">Description <a class="header-anchor" href="#description-63" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Solicitud de pre-alta web aprobada e ingreso oficial del socio consolidado.</p><h3 id="adc-user-inf-0002" tabindex="-1">ADC_USER_INF_0002 <a class="header-anchor" href="#adc-user-inf-0002" aria-label="Permalink to &quot;ADC\\_USER\\_INF\\_0002&quot;">​</a></h3><blockquote><p><strong>ADC_USER_INF_0002</strong>: <code>string</code> = <code>&#39;Usuario rechazado.&#39;</code></p></blockquote><h4 id="description-64" tabindex="-1">Description <a class="header-anchor" href="#description-64" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Notificación Toast de éxito: Registro pendiente destruído y purgado del panel operativo de la directiva.</p><h2 id="description-65" tabindex="-1">Description <a class="header-anchor" href="#description-65" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>Diccionario centralizado de mapeos y traducciones en lenguaje natural para la plataforma ADC Los Locos V2. Vincula de forma unívoca cada constante alfanumérica del enumerado <code>AppMessageCode</code> con su string representativo en español, proveyendo los textos oficiales que el <code>NotificationService</code> renderizará en los Toasts o alertas del ecosistema.</p>',269)])])}const _=a(t,[["render",c]]);export{u as __pageData,_ as default};
